import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Container } from '../../../components'
import OjkFooter from '../../../components/OjkFooter'
import LoginSlider from './components/LoginSlider'
import LoginForm from './components/LoginForm'
import { SignInWrapper } from './index.style'

export class SignIn extends Component {
  render () {
    const { history, sendOtpLoading, location } = this.props
    return (
      <Container loader={sendOtpLoading} hideBottomTabs>
        <SignInWrapper>
          <div>
            <LoginSlider />
            <LoginForm history={history} location={location} />
          </div>
          <OjkFooter black />
        </SignInWrapper>
      </Container>
    )
  }
}

export default connect((state) => ({
  sendOtpLoading: state.Loading.SEND_OTP
}),
{ })(SignIn)
