import { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Link } from 'react-router-dom'
import { Button } from '../../../../../components'
import AuthActions from '../../../../../redux/auth/action'
import ErrorActions from '../../../../../redux/error/action'
import LoadingActions from '../../../../../redux/loading/action'
import { setToLocalStorage } from '../../../../../helpers/localstorage'
import { REGISTRATION_DATA } from '../../../../../constants/cookies'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import NumericInput from '../../../../../components/NumericInput'
// import OTPMedium from '../OTPMedium'
import { typeValid } from '../../../../../helpers/validations'
import { addCountryCode } from '../../../../../helpers/utility'
import ShowSnackbar from '../../../../../components/ShowNotification'
import SendOtpModal from '../../../../../components/SendOtpModal'

const { sendOtp, verifyLoginNumber } = AuthActions
const { resetErrorRedux } = ErrorActions
const { resetLoadingRedux } = LoadingActions

class LoginForm extends Component {
  static propTypes = {
    history: PropTypes.object,
    location: PropTypes.object
  }

  state = {
    otpModal: false
  }

  componentDidMount () {
    // autoFocus the input in case user comes to
    // login page
    if (this.props.isLoggedIn) {
      this.props.history.push('/dashboard')
    } else {
      setTimeout(() => {
        const element = document.forms['login-form']
        if (element) {
          element.phone_no.focus()
        }
      }, 50)
    }
    this.props.resetErrorRedux(['SEND_OTP'])
    this.props.resetLoadingRedux(['SEND_OTP'])
  }

  componentDidUpdate (prevProps) {
    const { isLoggedIn, history } = this.props
    if (isLoggedIn && (prevProps.isLoggedIn !== isLoggedIn)) {
      history.push('/dashboard')
    }
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.sendOtpError && nextProps.sendOtpLoading === false) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: nextProps.sendOtpStatus
        })
      }
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    }
    if (nextProps.verifyNumberError && nextProps.verifyNumberLoading === false) {
      if (JSON.stringify(nextProps.verifyNumberStatus)?.includes('PIN-AUTH-ERR-1')) {
        if (ShowSnackbar.error) {
          ShowSnackbar.error({
            visible: true,
            text: 'Nomor ponsel tidak terdaftar'
          })
        }
      }
      if (JSON.stringify(nextProps.verifyNumberStatus)?.includes('PIN-AUTH-ERR-2') || JSON.stringify(nextProps.verifyNumberStatus)?.includes('PIN-AUTH-ERR-3')) {
        this.setState({
          otpModal: true
        })
      }
      this.props.resetErrorRedux(['VERIFY_LOGIN_NUMBER'])
      this.props.resetLoadingRedux(['VERIFY_LOGIN_NUMBER'])
    }
    if (nextProps.verifyNumberError === false && nextProps.verifyNumberLoading === false) { // if pin exist for agent
      this.props.history.push({
        pathname: '/login/pin',
        state: {
          phoneNo: this.phoneNumber
        }
      })
      this.props.resetErrorRedux(['VERIFY_LOGIN_NUMBER'])
      this.props.resetLoadingRedux(['VERIFY_LOGIN_NUMBER'])
    }
    if (nextProps.sendOtpError === false && nextProps.sendOtpLoading === false) {
      const { state } = this.props.location
      const body = { ...state, ...nextProps.sendOtpStatus, ...this.mobileValue }
      setToLocalStorage(REGISTRATION_DATA, body)
      this.props.history.push({ pathname: '/login/verify', state: body })
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    }
  }

  handlePhoneNumber = (value) => {
    this.phoneNumber = value
    if (this.state.error) {
      this.setState({ error: true })
    }
  }

  handleSubmit = () => {
    if (!typeValid('phone_number', this.phoneNumber)) {
      this.setState({ error: true })
      return
    }
    const body = {
      phone_no: this.props.isVNAgent ? addCountryCode(this.phoneNumber) : this.phoneNumber
    }
    if (!this.otpMedium) {
      body.channel = 'sms'
    }
    if (this.otpMedium === 'sms') {
      body.channel = this.otpMedium
    }
    if (this.otpMedium === 'whatsapp') {
      body.channel = this.otpMedium
    }
    if (this.otpMedium === 'email') {
      body.channel = this.otpMedium
    }
    this.mobileValue = {
      ...body
    }
    this.props.verifyLoginNumber({
      phone_no: this.phoneNumber,
      pin: ''
    })
  }

  onHandleSendOtp = (value) => {
    if (!typeValid('phone_number', this.phoneNumber)) {
      this.setState({ error: true })
      return
    }
    const body = {
      phone_no: this.props.isVNAgent ? addCountryCode(this.phoneNumber) : this.phoneNumber
    }
    if (value === 'whatsapp') {
      body.medium = value
    }
    this.mobileValue = {
      ...body
    }
    this.props.sendOtp(body)
  }

  handleMediumChange = (data) => {
    this.otpMedium = data.value
  }

  render () {
    return (
      <>
        <div className='login-form-box'>
          <NumericInput
            name='phone_no'
            type='phone_number'
            className='input-phone-number'
            placeholder='No Ponsel (08xxxxxxxx)'
            errorField={this.state.error && 'phone_no'}
            showError={this.state.error && ERROR_LANG.requiredField}
            errorCenter
            autoFocus
            onChange={this.handlePhoneNumber}
          />
          {/* {
            !this.props.isVNAgent && (
              <OTPMedium onMediumChange={this.handleMediumChange} />
            )
          } */}
          <Button onClick={this.handleSubmit} borderRadius='10px'>
            {LANG_STRINGS.login}
          </Button>
          <Link to='/registration'>
            <div className='sign-up-link'>
              Daftar Menjadi Mitra
            </div>
          </Link>

          <SendOtpModal
            show={this.state.otpModal}
            handleSubmit={this.onHandleSendOtp}
            onClose={() =>
              this.setState({ otpModal: false })}
          />
        </div>
      </>
    )
  }
}

export default connect((state) => ({
  sendOtpLoading: state.Loading.SEND_OTP,
  sendOtpError: state.Error.SEND_OTP,
  isVNAgent: state.Auth.isVNAgent,
  sendOtpStatus: state.Auth.sendOtpStatus,
  verifyNumberStatus: state.Auth.verifyNumberStatus,
  verifyNumberLoading: state.Loading.VERIFY_LOGIN_NUMBER,
  verifyNumberError: state.Error.VERIFY_LOGIN_NUMBER
}), {
  resetErrorRedux,
  resetLoadingRedux,
  sendOtp,
  verifyLoginNumber
})(LoginForm)
